    class CharCount:
        def __init__(self,c,count):
            self.c=c;self.count=count
    def removeDuplicates(self,s,k):
        stack=[]
        for c in s:
            if(len(stack)==0):
                stack.append(Solution3.CharCount(c,1))
            else:
                if(stack[-1].c==c and stack[-1].count+1==k):
                    stack.pop()
                elif(stack[-1].c==c):
                    stack.append(Solution3.CharCount(c,stack[-1].count+1));stack.pop(-2)
                else:
                    stack.append(Solution3.CharCount(c,1))
        sb=''
        while(len(stack)!=0):
            pair=stack.pop()
            count=pair.count
            while(count>0):
                sb+=pair.c;count-=1
        return sb[::-1]

